def CREDO_FLD_WR(_reg_val, _fld_val, _hi, _lo):
  reg_val = int(_reg_val)
  fld_val = int(_fld_val)
  hi = int(_hi)
  lo = int(_lo)
  return ((reg_val >> lo) << (32 - hi - 1 + lo) >> (32 - hi - 1) | (fld_val << lo))

def CREDO_FLD_RD(_reg_val, _hi, _lo):
  reg_val = int(_reg_val)
  hi = int(_hi)
  lo = int(_lo)
  return ((reg_val << (32 - hi - 1)) >> (32 - hi - 1 + lo))

CREDO_BLK_TX = 0
CREDO_BLK_RX = 1
CREDO_BLK_RSVD = 2
CREDO_BLK_FEC_ANALYZER = 3
CREDO_BLK_LANE_SLICE = 4
CREDO_BLK_LINK_TRNG = 5
CREDO_BLK_AN_LT = 6
CREDO_BLK_AN_IEEE = 7
CREDO_BLK_AN_RSVD = 8
CREDO_BLK_GROUP8 = 9
CREDO_BLK_DFX_EVEN = 10
CREDO_BLK_DFX_ODD = 11
CREDO_BLK_TOP_PLL = 12
CREDO_BLK_ECC = 13
CREDO_BLK_RSVD2 = 14
CREDO_BLK_SENSOR = 15
CREDO_BLK_RSVD3 = 16
CREDO_BLK_GPIO = 17
CREDO_BLK_FW = 18

#********************************************************************/
# credo_map_blk_offset_to_addr
#********************************************************************/
def credo_map_blk_offset_to_addr(blk_index, offset, ln):
    offset_mask = 0x000FF
    if blk_index ==  CREDO_BLK_TX:
        addr   = 0x00000
        stride = 0x10000
    elif blk_index == CREDO_BLK_RX:
        addr   = 0x00100
        stride = 0x10000
    elif blk_index == CREDO_BLK_RSVD:
        addr   = 0x000C0
        stride = 0x10000
        offset_mask = 0x0003F # special mask for offset
    elif blk_index == CREDO_BLK_FEC_ANALYZER:
        addr   = 0x001C0
        stride = 0x10000
        offset_mask = 0x000F # special mask for offset
    elif blk_index == CREDO_BLK_LANE_SLICE:
        addr   = 0x00200
        stride = 0x10000
    elif blk_index == CREDO_BLK_LINK_TRNG:
        addr   = 0x00400
        stride = 0x10000
    elif blk_index == CREDO_BLK_AN_LT:
        addr   = 0x00300
        stride = 0x10000
    elif blk_index == CREDO_BLK_AN_IEEE:
        addr   = 0x00500
        stride = 0x10000
    elif blk_index == CREDO_BLK_AN_RSVD:
        addr   = 0x00600
        stride = 0x10000
    elif blk_index == CREDO_BLK_GROUP8:
        addr   = 0x80100
        stride = 0x0
    elif blk_index == CREDO_BLK_DFX_EVEN:
        addr   = 0x80100
        stride = 0x0020
    elif blk_index == CREDO_BLK_DFX_ODD:
        addr   = 0x80110
        stride = 0x0020
    elif blk_index == CREDO_BLK_TOP_PLL:
        addr   = 0x90000
        stride = 0x0
    elif blk_index == CREDO_BLK_ECC:
        addr   = 0x90200
        stride = 0x0
    elif blk_index == CREDO_BLK_SENSOR:
        addr   = 0x90300
        stride = 0x0
    elif blk_index == CREDO_BLK_GPIO:
        addr   = 0x90400
        stride = 0x0
    elif blk_index == CREDO_BLK_FW:
        addr   = 0xA0000
        stride = 0x0
    else:
        addr   = 0xBAD00
        stride = 0x0
    return (addr + (ln * stride) + (offset & offset_mask))

#********************************************************************/
# credo_reg_rd
#********************************************************************/
def credo_reg_rd(dev_id, dev_port, ln, blk_index, offset):
  reg_ofs  = credo_map_blk_offset_to_addr(blk_index, offset, ln)

  reg_val = credo_hw_reg_rd(dev_id, dev_port, reg_ofs)
  return reg_val

#********************************************************************/
# credo_reg_wr
#********************************************************************/
def credo_reg_wr(dev_id, dev_port, ln, blk_index, offset, reg_val):
  reg_ofs  = credo_map_blk_offset_to_addr(blk_index, offset, ln)

  credo_hw_reg_wr(dev_id, dev_port, reg_ofs, reg_val)
  return

#*********************************************************************
# credo_group8_0x0_rsvd_080000_15_get
# 
# Reserved. Do not change the default value.
#********************************************************************/
def credo_group8_0x0_rsvd_080000_15_get(dev_id, dev_port, ln):
  reg_val = credo_reg_rd(dev_id, dev_port, ln, CREDO_BLK_GROUP8, 0x0)
  val = CREDO_FLD_RD(reg_val, 15, 15)
  return val

#*********************************************************************
# credo_group8_0x0_rsvd_080000_15_set
# 
# Reserved. Do not change the default value.
#********************************************************************/
def credo_group8_0x0_rsvd_080000_15_set(dev_id, dev_port, ln, val):
  reg_val = credo_reg_rd(dev_id, dev_port, ln, CREDO_BLK_GROUP8, 0x0)
  CREDO_FLD_WR(reg_val, val, 15, 15)
  credo_reg_wr(dev_id, dev_port, ln, CREDO_BLK_GROUP8, 0x0, reg_val);

#*********************************************************************
# credo_group8_0x0_rsvd_080000_15_show
# 
# Reserved. Do not change the default value.
#********************************************************************/
def credo_group8_0x0_rsvd_080000_15_show(dev_id, dev_port, ln, val):
  reg_ofs  = credo_map_blk_offset_to_addr(CREDO_BLK_GROUP8, 0x0, ln )

  print("# Reserved. Do not change the default value.\n")
  phys_addr = reg_ofs
  print(hex(phys_addr) + " : " + "group8" + " : " + hex(reg_ofs) + " : " + hex(val))
